class Solution:
    def maximumSumQueries(self, nums1, nums2, queries):
        res = []
        for x, y in queries:
            best = -1
            for a, b in zip(nums1, nums2):
                if a >= x and b >= y:
                    best = max(best, a + b)
            res.append(best)
        return res

