class Solution {
public:
    vector<int> maximumSumQueries(vector<int>& nums1, vector<int>& nums2, vector<vector<int>>& queries) {
        vector<int> res;
        for (auto& q : queries) {
            int best = -1;
            for (int j = 0; j < (int)nums1.size(); j++)
                if (nums1[j] >= q[0] && nums2[j] >= q[1])
                    best = max(best, nums1[j] + nums2[j]);
            res.push_back(best);
        }
        return res;
    }
};

