class Solution:
    def maximumSumQueries(self, nums1, nums2, queries):
        pts = sorted(zip(nums1, nums2))
        qs = sorted(((x, y, i) for i, (x, y) in enumerate(queries)), reverse=True)
        st = []
        res = [-1] * len(queries)
        p = len(pts) - 1
        import bisect
        for x, y, qi in qs:
            while p >= 0 and pts[p][0] >= x:
                a, b = pts[p]; p -= 1
                cur = a + b
                while st and st[-1][0] <= b:
                    cur = max(cur, st.pop()[1])
                if not st or st[-1][1] < cur:
                    st.append([b, cur])
            bs = [e[0] for e in st]
            k = bisect.bisect_left(bs, y)
            if k < len(st):
                res[qi] = st[k][1]
        return res

