class Solution {
public:
    vector<int> maximumSumQueries(vector<int>& nums1, vector<int>& nums2, vector<vector<int>>& queries) {
        int n = nums1.size(), q = queries.size();
        vector<int> id(n), qid(q);
        iota(id.begin(), id.end(), 0);
        iota(qid.begin(), qid.end(), 0);
        sort(id.begin(), id.end(), [&](int a, int b){ return nums1[a] > nums1[b]; });
        sort(qid.begin(), qid.end(), [&](int a, int b){ return queries[a][0] > queries[b][0]; });
        vector<pair<int,int>> st;
        vector<int> res(q, -1);
        int p = 0;
        for (int qi : qid) {
            int x = queries[qi][0], y = queries[qi][1];
            while (p < n && nums1[id[p]] >= x) {
                int j = id[p++];
                int b = nums2[j], cur = nums1[j] + b;
                while (!st.empty() && st.back().first <= b) {
                    cur = max(cur, st.back().second);
                    st.pop_back();
                }
                if (st.empty() || st.back().second < cur)
                    st.push_back({b, cur});
            }
            int lo = 0, hi = st.size();
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (st[mid].first >= y) hi = mid; else lo = mid + 1;
            }
            if (lo < (int)st.size()) res[qi] = st[lo].second;
        }
        return res;
    }
};

