class Solution {
    public int[] maximumSumQueries(int[] nums1, int[] nums2, int[][] queries) {
        int n = nums1.length, q = queries.length;
        Integer[] id = new Integer[n], qid = new Integer[q];
        for (int i = 0; i < n; i++) id[i] = i;
        for (int i = 0; i < q; i++) qid[i] = i;
        Arrays.sort(id, (a, b) -> nums1[b] - nums1[a]);
        Arrays.sort(qid, (a, b) -> queries[b][0] - queries[a][0]);
        List<long[]> st = new ArrayList<>();
        int[] res = new int[q];
        Arrays.fill(res, -1);
        int p = 0;
        for (int qi : qid) {
            int x = queries[qi][0], y = queries[qi][1];
            while (p < n && nums1[id[p]] >= x) {
                int j = id[p++];
                int b = nums2[j], cur = nums1[j] + b;
                while (!st.isEmpty() && (int) st.get(st.size()-1)[0] <= b) {
                    cur = Math.max(cur, (int) st.remove(st.size()-1)[1]);
                }
                if (st.isEmpty() || (int) st.get(st.size()-1)[1] < cur)
                    st.add(new long[]{b, cur});
            }
            int lo = 0, hi = st.size();
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if ((int) st.get(mid)[0] >= y) hi = mid; else lo = mid + 1;
            }
            if (lo < st.size()) res[qi] = (int) st.get(lo)[1];
        }
        return res;
    }
}

